begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into auth.users(id,email) values ('89000000-0000-4000-8000-000000000001','orders-admin@example.invalid');
insert into public.profiles(id,full_name,role) values ('89000000-0000-4000-8000-000000000001','Orders admin','admin') on conflict(id) do update set role='admin';
insert into auth.mfa_factors(id,user_id,factor_type,status,secret,created_at,updated_at) values ('89000000-0000-4000-8000-000000000002','89000000-0000-4000-8000-000000000001','totp','verified','LOCAL-TEST-ONLY',now(),now());
insert into public.sessions(id,owner_id,name,date,start_time,max_players,game_options,confirmed_game_id,booking_type,ticket_total_price)
values ('89000000-0000-4000-8000-000000000003','89000000-0000-4000-8000-000000000001','Orders fixture',current_date+190,'17:00',1,array['city-z'],'city-z','ticket',240000);
insert into public.staff_orders(id,order_number,session_id,game_id,arena_id,booking_date,booking_time,players_count,total,subtotal,order_status)
values ('89000000-0000-4000-8000-000000000004','ORDERS-SPLITS-TEST','89000000-0000-4000-8000-000000000003',(select id from public.staff_games where slug='city-z'),'arena-1',current_date+190,'17:00',1,240000,240000,'confirmed');
create temp table split_payloads(name text, payload jsonb);
insert into split_payloads values ('valid','[{"id":"89000000-0000-4000-8000-000000000011","method":"cash","amount":40000},{"id":"89000000-0000-4000-8000-000000000012","method":"card_manual","amount":60000}]');
grant select on split_payloads to authenticated;
select ok(not has_function_privilege('anon','public.staff_record_order_payments(uuid,jsonb)','execute'),'Anon cannot save split payments');
select ok(not has_function_privilege('anon','public.staff_adjust_order_total(uuid,integer,text,timestamptz)','execute'),'Anon cannot reprice');
select ok(not has_function_privilege('anon','public.staff_set_order_status(uuid,text,timestamptz)','execute'),'Anon cannot change status');
set local role authenticated;
select set_config('request.jwt.claims','{"role":"authenticated","sub":"89000000-0000-4000-8000-000000000001","aal":"aal1"}',true);
select throws_ok($q$select public.staff_record_order_payments('89000000-0000-4000-8000-000000000004',(select payload from split_payloads where name='valid'))$q$,'P0001','Staff access required.','Split payment requires MFA');
select throws_ok($q$select public.staff_adjust_order_total('89000000-0000-4000-8000-000000000004',300000,'test',now())$q$,'P0001','Staff access required.','Reprice requires MFA');
select throws_ok($q$select public.staff_set_order_status('89000000-0000-4000-8000-000000000004','no_show',now())$q$,'P0001','Staff access required.','Status change requires MFA');
select set_config('request.jwt.claims','{"role":"authenticated","sub":"89000000-0000-4000-8000-000000000001","aal":"aal2"}',true);
select throws_ok($q$select public.staff_record_order_payments('89000000-0000-4000-8000-000000000004','[{"id":"89000000-0000-4000-8000-000000000021","method":"cash","amount":40000},{"id":"89000000-0000-4000-8000-000000000022","method":"card_manual","amount":300000}]')$q$,'P0001','Payment exceeds the remaining balance. Refresh the order and check the amount.','Overpaid split batch is rejected');
select is((select count(*)::int from public.staff_order_payments where order_id='89000000-0000-4000-8000-000000000004'),0,'Failed batch rolls back its first receipt');
select lives_ok($q$select public.staff_record_order_payments('89000000-0000-4000-8000-000000000004',(select payload from split_payloads where name='valid'))$q$,'Two-method split saves atomically');
select lives_ok($q$select public.staff_record_order_payments('89000000-0000-4000-8000-000000000004',(select payload from split_payloads where name='valid'))$q$,'Retry succeeds');
select is((select count(*)::int from public.staff_order_payments where order_id='89000000-0000-4000-8000-000000000004'),2,'Retry does not duplicate splits');
select is((select payment_status||'/'||payment_method from public.staff_orders where order_number='ORDERS-SPLITS-TEST'),'partially_paid/split','Partial split status is accurate');
select throws_ok($q$select public.staff_adjust_order_total(id,300000,' ',updated_at) from public.staff_orders where order_number='ORDERS-SPLITS-TEST'$q$,'P0001','A reason is required for a price adjustment.','Blank reason rejected');
select throws_ok($q$select public.staff_adjust_order_total(id,300000,'Package change','2000-01-01') from public.staff_orders where order_number='ORDERS-SPLITS-TEST'$q$,'P0001','This order has changed. Refresh it before saving.','Stale total edit rejected');
select throws_ok($q$select public.staff_adjust_order_total(id,90000,'Package change',updated_at) from public.staff_orders where order_number='ORDERS-SPLITS-TEST'$q$,'P0001','The total cannot be lower than recorded payments.','Cannot reprice below receipts');
select lives_ok($q$select public.staff_adjust_order_total(id,300000,'Agreed transfer package',updated_at) from public.staff_orders where order_number='ORDERS-SPLITS-TEST'$q$,'Reason-bearing total correction succeeds');
select is((select ticket_total_price from public.sessions where id='89000000-0000-4000-8000-000000000003'),300000,'Calendar amount follows agreed total');
select is((select price_override_original_total from public.staff_orders where order_number='ORDERS-SPLITS-TEST'),240000,'Original total is retained');
select is((select sum(amount)::int from public.staff_order_payments where order_id='89000000-0000-4000-8000-000000000004'),100000,'Reprice keeps receipts');
select throws_ok($q$select public.staff_update_order_operation(id,game_id,booking_date,booking_time,90000) from public.staff_orders where order_number='ORDERS-SPLITS-TEST'$q$,'P0001','Use Adjust total and enter a reason for the price change.','Old total editor cannot bypass the mandatory reason');
select lives_ok($q$select public.staff_set_order_status(id,'no_show',updated_at) from public.staff_orders where order_number='ORDERS-SPLITS-TEST'$q$,'No-show is applied atomically');
select is((select status from public.sessions where id='89000000-0000-4000-8000-000000000003'),'cancelled','No-show releases the calendar slot');
select is((select sum(amount)::int from public.staff_order_payments where order_id='89000000-0000-4000-8000-000000000004'),100000,'No-show keeps receipts');
select throws_ok($q$select public.staff_set_order_status(id,'completed',updated_at) from public.staff_orders where order_number='ORDERS-SPLITS-TEST'$q$,'P0001','This order is already closed. Review its booking before changing the status.','Closed order cannot accidentally become completed');
reset role;
select * from finish();
rollback;
